\label{thm:main}
There exists a countable one-dimensional Cohen--Macaulay local ring $R$ such that $\mathcal{GI}(R)$ is not precovering.
More precisely, there is a sequence $(G_n)_{n\in\mathbb N_+}$ of Gorenstein injective $R$-modules such that $M=\coprod_{n\in\mathbb N_+}G_n$ has infinite Gorenstein injective dimension and admits no Gorenstein injective precover.

\label{thm:locality}
Let $X$ be a Noetherian scheme. The following conditions are equivalent.
\begin{enumerate}
\item For every open subscheme $U\subseteq X$, $\mathcal{GI}(\mathcal A_U)$ forms a covering class.
\item $\mathcal{GI}(\mathcal A_X)$ forms a covering class.
\item There is an open cover $X=\bigcup_{i\in I}U_i$ such that $\mathcal{GI}(\mathcal A_{U_i})$ forms a covering class for every $i\in I$.
\item There is an affine open cover $X=\bigcup_{i\in I}\mathrm{Spec}\,R_i$ such that $\mathcal{GI}(R_i)$ forms a covering class for every $i\in I$.
\item For every open cover $X=\bigcup_{i\in I}U_i$, $\mathcal{GI}(\mathcal A_{U_i})$ forms a covering class for every $i\in I$.
\item For every affine open cover $X=\bigcup_{i\in I}\mathrm{Spec}\,R_i$, $\mathcal{GI}(R_i)$ forms a covering class for every $i\in I$.
\end{enumerate}

\label{lem:precovering-noetherian}
Let $\mathcal A$ be a locally finitely generated Grothendieck category.
If $\mathcal{GI}(\mathcal A)$ forms a precovering class, then $\mathcal A$ is locally Noetherian.

\label{lem:gi-preenvelope}
  For each $X \in \mathcal{A}$, denote the embedding $\iota_X : X \to \prod_{\mathrm{Hom}_\mathcal{A}(X,J)}J$.
  Then for each $G \in \mathcal{GI}(\mathcal{A})$, the short exact sequence $0 \to G \xrightarrow{\iota_G} \prod_{\mathrm{Hom}_\mathcal{A}(G,J)}J \to \mathrm{coker} \iota_G \to 0$ remains exact after applying $\mathrm{Hom}_\mathcal{A}(E,-)$ for each $E \in \mathcal{E}$, and $\mathrm{coker} \iota_G \in \mathcal{GI}(\mathcal{A})$.

\label{lem:localizing-colimit}
Let $\mathcal A$ be a locally Noetherian Grothendieck category and let $T:D\to\mathrm{Ch}(\mathrm{Inj}\,\mathcal A)$ be a filtered diagram of complexes of injective objects and chain maps.
Then its colimit in $\mathrm{Ch}(\mathcal A)$ is a complex of injective objects representing the homotopy colimit.

\label{lem:localising-hocolimits}
Let $\mathcal M$ be a stable combinatorial model category and let $\mathcal S$ be a localising subcategory of $\mathrm{Ho}(\mathcal M)$.
For any small diagram $F:D\to\mathcal M$ whose values represent objects of $\mathcal S$, one has $\mathrm{hocolim}_D F\in\mathcal S$.

\label{cor:localizing-colimit}
Let $\mathcal A$ be a locally Noetherian Grothendieck category and let $\mathcal L$ be a localising subcategory of $K(\mathrm{Inj}\,\mathcal A)$.
If $T:D\to\mathcal L$ is a filtered diagram, then its colimit in $\mathrm{Ch}(\mathcal A)$ belongs to $\mathcal L$.

\label{lem:tac-approximations}
Let $\mathcal A$ be a locally Noetherian Grothendieck category, and let $\mathcal C$ be the class of totally acyclic complexes of injective objects in $\mathrm{Ch}(\mathcal A)$.
If $\mathcal{GI}(\mathcal A)$ is closed under filtered colimits, then $\mathcal C$ is a covering class in $\mathrm{Ch}(\mathcal A)$.

\label{cor:tac-covers-to-gi-covers}
Let $\mathcal A$ be an abelian category with enough injective objects.
If the totally acyclic complexes of injective objects form a covering class in $\mathrm{Ch}(\mathcal A)$, then $\mathcal{GI}(\mathcal A)$ forms a covering class in $\mathcal A$.

\label{cor:gi-covering-from-colimits}
Let $\mathcal A$ be a locally Noetherian Grothendieck category.
If $\mathcal{GI}(\mathcal A)$ is closed under filtered colimits, then it forms a covering class.

\label{prop:leftadj}
    The following statements are equivalent:
    \begin{enumerate}
        \item $i_\ast$ admits a left adjoint $i^\ast$,
        \item $({}^\perp \mathcal{GI}(\mathcal A), \mathcal{GI}(\mathcal A))$ is a complete cotorsion pair,
        \item there exists a generator $U \in \mathcal A$ such that $U \in {}^\perp \mathcal{GI}(\mathcal A)$.
    \end{enumerate}

\label{lem:dimA}
One has
\(\operatorname{Spec} A=\{(0),\mathfrak m_A\}\) and \(\dim A=1\).

The first isomorphism follows since $Y$ is finite-dimensional;
the second follows by extension of scalars.
Thus $C$ is finitely generated over $A$ and so is over $R$.

\label{c:open-adjoints}
Then adjunction $u^\ast \dashv u_\ast$ of quasicoherent sheaves degreewise induces the adjoint pair  between $\mathcal T_U$ and $\mathcal T_X$, which is again denoted by $u^\ast \dashv u_\ast$.
Moreover, $u_\ast : \mathcal T_U \to \mathcal T_X$ admits a right adjoint, which is denoted by $u^\times$.
The functors are
\[
\xymatrix@C=1.4cm{
U \ \ar@{^{(}->}[r]^u & X
}
\qquad
\xymatrix@C=2cm{
\mathcal A_U \ar[r]|{u_\ast}
& \mathcal A_X \ar@<-1.2ex>[l]_{u^\ast}
}
\qquad
\xymatrix@C=2cm{
\mathcal T_U \ar[r]|{u_\ast}
& \mathcal T_X
  \ar@<-1.2ex>[l]_{u^\ast}
  \ar@<1.2ex>[l]^{u^\times}
}
\]

\label{c:tac-adjunction}
The adjoint triple $u^\ast \dashv u_\ast \dashv u^\times$ induces the adjoint pair $\widetilde{u_\ast}\dashv \widetilde{u^\times}$
\[
\xymatrix@C=3.5cm@R=.7cm{
\mathcal T_U
\ar[r]|{u_\ast}
& \mathcal T_X
\ar@<-1.2ex>[l]_{u^\ast}
\ar@<1.2ex>[l]^{u^\times}
\\
\mathcal S_U
\ar@{ >->}[u]^{i_U{}_{\ast}}
\ar@{.>}[r]|{\widetilde{u_\ast}}
& \mathcal S_X
\ar@{ >->}[u]_{i_X{}_{\ast}}
\ar@{.>}@<1.2ex>[l]^{\widetilde{u^\times}}
}
\]
with $u_\ast i_U{}_\ast = i_X{}_\ast \widetilde{u_\ast}$ and $u^\times i_X{}_\ast = i_U{}_\ast \widetilde{u^\times}$.

\label{c:restriction-recollements}
Suppose that $\mathcal{GI}(\mathcal A_X)$ is covering, and put
$\mathcal Q_Y=\mathcal T_Y/\mathcal S_Y$ for $Y=X,U$.
Then $u^\ast$ preserves total acyclicity.
The horizontal rows in the following diagram are recollements, and each vertical column is an adjoint triple:
\[
\xymatrix@C=4cm@R=1.5cm{
\mathcal S_U
\ar@{ >->}[r]|{i_U{}_\ast}
\ar[d]|{\widetilde{u_\ast}}
&
\mathcal T_U
\ar@<1.1ex>[l]^{i_U{}^!}
\ar@<-1.1ex>[l]_{i_U{}^\ast}
\ar[r]|{j_U{}^\ast}
\ar[d]|{u_\ast}
&
\mathcal Q_U
\ar@<1.1ex>[l]^{j_{U\ast}}
\ar@<-1.1ex>[l]_{j_{U!}}
\ar[d]|{\widehat{u_\ast}}
\\
\mathcal S_X
\ar@{ >->}[r]|{i_X{}_\ast}
\ar@<1.1ex>[u]^{\widetilde{u^\ast}}
\ar@<-1.1ex>[u]_{\widetilde{u^\times}}
&
\mathcal T_X
\ar@<1.1ex>[l]^{i_X{}^!}
\ar@<-1.1ex>[l]_{i_X{}^\ast}
\ar[r]|{j_X{}^\ast}
\ar@<1.1ex>[u]^{u^\ast}
\ar@<-1.1ex>[u]_{u^\times}
&
\mathcal Q_X
\ar@<1.1ex>[l]^{j_{X\ast}}
\ar@<-1.1ex>[l]_{j_{X!}}
\ar@<1.1ex>[u]^{\widehat{u^\ast}}
\ar@<-1.1ex>[u]_{\widehat{u^\times}}
}
\]
Here $j_Y{}^\ast$ is the quotient functor, with
$j_{Y!}\dashv j_Y{}^\ast\dashv j_{Y\ast}$.
The central squares commute:
\[
\begin{aligned}
u_\ast i_U{}_\ast
&\cong i_X{}_\ast\widetilde{u_\ast},
&\qquad u^\ast i_X{}_\ast
&\cong i_U{}_\ast\widetilde{u^\ast},
&\qquad u^\times i_X{}_\ast
&\cong i_U{}_\ast\widetilde{u^\times},\\
j_X{}^\ast u_\ast
&\cong\widehat{u_\ast}j_U{}^\ast,
&\qquad j_U{}^\ast u^\ast
&\cong\widehat{u^\ast}j_X{}^\ast,
&\qquad j_U{}^\ast u^\times
&\cong\widehat{u^\times}j_X{}^\ast.
\end{aligned}
\]

\label{cor:ais}
If $\mathcal S_X$ is localising, then
$A\star I\in\mathcal S_X$ for all $A\in\mathcal D_X$ and $I\in\mathcal S_X$.

\label{c:lem:artin-periodic}
There is a Gorenstein injective $\bigl(X_i\otimes_{K_i}Y_i\bigr)$-module $L_i$ with an exact sequence
\begin{equation}\label{c:eq:Lperiodic}
0\longrightarrow L_i\longrightarrow I_i^0\longrightarrow L_i\longrightarrow0,
\qquad I_i^0\text{ injective over }\bigl(X_i\otimes_{K_i}Y_i\bigr),
\end{equation}
and $\mathrm{Ext}_{X_i\otimes_{K_i}Y_i}^j(\bigl(X_i\otimes_{K_i}Y_i^*\bigr),L_i)\ne0$ for each $j \geq 1$.

\label{c:restriction}
Let $S$ be a commutative Noetherian ring and $\Sigma\subseteq S$ a multiplicative set.
Every Gorenstein injective $\Sigma^{-1}S$-module is Gorenstein injective over $S$.

A straightforward calculation gives
\begin{align*}
\frac{\Omega_{\mathfrak m_i}}{t_i^3\Omega_{\mathfrak m_i}}
&\cong \Omega_{\mathfrak m_i}
\otimes_{B_{\mathfrak m_{B,i}}}
\frac{B_{\mathfrak m_{B,i}}}
{t_i^3B_{\mathfrak m_{B,i}}} \cong \Omega_{\mathfrak m_i}
\otimes_{B_{\mathfrak m_{B,i}}}
\frac{K_i[a,b]}{(a,b)^2} =\Omega_{\mathfrak m_i}
\otimes_{B_{\mathfrak m_{B,i}}}X_i \cong \Omega_{\mathfrak m_i}
\otimes_{B_{\mathfrak m_{B,i}}}X_i\\
&\cong \bigl(\Omega\otimes_B B_{\mathfrak m_{B,i}}\bigr)
\otimes_{B_{\mathfrak m_{B,i}}}X_i = \bigl(\mathrm{Hom}_B(S,B)
\otimes_B B_{\mathfrak m_{B,i}}\bigr)
\otimes_{B_{\mathfrak m_{B,i}}}X_i\\
&\cong \mathrm{Hom}_{B_{\mathfrak m_{B,i}}}
\bigl(S\otimes_B B_{\mathfrak m_{B,i}},
B_{\mathfrak m_{B,i}}\bigr)
\otimes_{B_{\mathfrak m_{B,i}}}X_i \cong \mathrm{Hom}_{B_{\mathfrak m_{B,i}}}
\bigl(S_{\mathfrak m_i},B_{\mathfrak m_{B,i}}\bigr)
\otimes_{B_{\mathfrak m_{B,i}}}X_i\\
&\cong \mathrm{Hom}_{X_i}
\bigl(S_{\mathfrak m_i}\otimes_{B_{\mathfrak m_{B,i}}}X_i,X_i\bigr)\cong \mathrm{Hom}_{X_i}
\bigl(S_{\mathfrak m_i}/t_i^3S_{\mathfrak m_i},X_i\bigr)\\
&\cong \mathrm{Hom}_{X_i}(X_i\otimes_{K_i}Y_i,X_i)
\cong X_i\otimes_{K_i}\mathrm{Hom}_{K_i}(Y_i,K_i) \quad = X_i\otimes_{K_i}Y_i^*.
\end{align*}
It follows that 
\[
\begin{aligned}
\mathrm{Ext}_{S_{\mathfrak m_i}}^1(\Omega_{\mathfrak m_i},H_i)
&\cong\mathrm{Ext}_{S_{\mathfrak m_i}}^2(\Omega_{\mathfrak m_i},L_i) \cong\mathrm{Ext}_{S_{\mathfrak m_i}/t_i^3S_{\mathfrak m_i}}^2
\left(\frac{\Omega_{\mathfrak m_i}}{t_i^3\Omega_{\mathfrak m_i}},L_i\right)\\
&\cong\mathrm{Ext}_{X_i\otimes_{K_i}Y_i}^2
(X_i\otimes_{K_i}Y_i^*,L_i)\ne0.
\end{aligned}
\]
The final inequality follows from Lemma~\ref{c:lem:artin-periodic}.

